using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Windows.Forms;using JouchoPet;
class EyePlacementCheck {
 const string Folder="qa/v0735/";const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static|BindingFlags.Instance;static int checks;
 static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static object ConvertValue(object v,Type t){if(t.IsPrimitive||t==typeof(string))return v;object o=Activator.CreateInstance(t);foreach(var f in t.GetFields(F)){var s=v.GetType().GetField(f.Name,F);if(s!=null)f.SetValue(o,ConvertValue(s.GetValue(v),f.FieldType));}return o;}
 static double BlueY(Bitmap b,int size){var p=PoseMesh.Read(b);double n=0,total=0;for(int y=28+(int)(size*.15);y<28+size*.29;y++)for(int x=b.Width/2;x<b.Width/2+size*.18;x++){uint c=(uint)p[y*b.Width+x];double weight=Math.Max(0,(c&255)-(int)(c>>16&255)-10);if((c>>24)>180){n+=y*weight;total+=weight;}}return n/total;}
 static RenderFrame Frame(string kind,double age=1){var f=new RenderFrame{MotionState="idle",Time=0};if(kind=="blink")f.Blink=1;if(kind=="wink")f.Daily=DailyMotion.At(DailyAction.Wink,.6);if(kind=="pat"){f.Affection=1;f.ClosedEyes=1;}if(kind=="wave"){f.Greeting=1;f.WaveBlend=1;f.ClosedEyes=1;f.WavePhase=.5;}if(kind=="left"||kind=="right"){f.MotionState="hold";f.Facing=kind=="left"?-1:1;}if(kind=="turn-left"||kind=="turn-right"){f.MotionState="turn";f.Angle=kind=="turn-left"?-.5:.5;}if(kind=="sleep")f.RestAmount=1;return f;}
 static void Cell(Graphics g,Bitmap image,int x,int width,int height,string label){g.DrawString(label,SystemFonts.DefaultFont,Brushes.White,x+6,4);g.DrawImageUnscaled(image,x,24);var head=new Rectangle(image.Width/2-(int)(width*.30),22,(int)(width*.60),(int)(height*.34));g.DrawImage(image,new Rectangle(x,height+26,width,(int)(width*.56)),head,GraphicsUnit.Pixel);}
 [STAThread]static void Main(string[] args){try{AnimationParameters.UseFixedValues();Directory.CreateDirectory(Folder);if(args.Length>0&&args[0]=="live"){Live();return;}var old=Assembly.LoadFile(Path.GetFullPath(Folder+"baseline/IsekaijouchoPet.exe"));var art=old.GetType("JouchoPet.CharacterArt");
 foreach(int size in new[]{220,300,400}){var c=PetRenderer.CanvasSize(size);foreach(string name in new[]{"front","profile-left","left","right","profile-right","pat","sleep","crouch"})using(var before=(Bitmap)art.GetMethod("Normalized",F).Invoke(null,new object[]{name,c.Width,c.Height,(double)size}))using(var after=CharacterArt.Normalized(name,c.Width,c.Height,size)){var a=PoseMesh.Read(before);var b=PoseMesh.Read(after);bool unchanged=true;for(int y=(int)(28+size*.32);y<c.Height;y++)for(int x=0;x<c.Width;x++)unchanged&=a[y*c.Width+x]==b[y*c.Width+x];Check(unchanged,"body unchanged / "+name+" / "+size);if(name=="sleep"||name=="crouch")Check(a.SequenceEqual(b),"frozen artwork unchanged / "+name+" / "+size);if(name=="front"){double delta=BlueY(before,size)-BlueY(after,size);Check(Math.Abs(delta-EyePlacement.Rise(size))<.4,"blue eye moves upward with ink / "+size+" / "+delta.ToString("F2"));}}
 using(var now=new PetRenderer()){now.Resize(size);var type=old.GetType("JouchoPet.PetRenderer");object previous=Activator.CreateInstance(type,true);type.GetMethod("Resize",F).Invoke(previous,new object[]{size});try{string[] names={"idle","blink","wink","pat","wave","left","right","turn-left","turn-right","sleep"};foreach(string name in names){var frame=Frame(name);var before=(Bitmap)type.GetMethod("Draw",F).Invoke(previous,new[]{ConvertValue(frame,old.GetType("JouchoPet.RenderFrame"))});var after=now.Draw(frame);using(var sheet=new Bitmap(c.Width*2,c.Height+30+(int)(c.Width*.56)))using(var g=Graphics.FromImage(sheet)){g.Clear(Color.FromArgb(42,47,57));Cell(g,before,0,c.Width,c.Height,"0.7.34");Cell(g,after,c.Width,c.Width,c.Height,"0.7.35");sheet.Save(Folder+name+"-"+size+".png");}if(name=="sleep")Check(PoseMesh.Read(before).SequenceEqual(PoseMesh.Read(after)),"frozen sleep render unchanged / "+size);}
 var open=PoseMesh.Read(now.Draw(Frame("idle")));var wink=PoseMesh.Read(now.Draw(Frame("wink")));bool rightUntouched=true;for(int y=0;y<c.Height;y++)for(int x=0;x<c.Width/2;x++)rightUntouched&=open[y*c.Width+x]==wink[y*c.Width+x];Check(rightUntouched,"wink keeps anatomical right eye unchanged / "+size);
 }finally{((IDisposable)previous).Dispose();}}}
 Console.WriteLine("All "+checks+" checks passed.");}catch(Exception e){Console.WriteLine(e);Environment.ExitCode=1;}}
 static void Live(){Application.EnableVisualStyles();using(var r=new PetRenderer())using(var host=new Form{Text="眼睛位置验收 v0.7.35",Width=760,Height=750,BackColor=Color.FromArgb(42,47,57),StartPosition=FormStartPosition.CenterScreen}){r.Resize(300);var image=new PictureBox{Left=20,Top=70,Width=680,Height=600,SizeMode=PictureBoxSizeMode.Zoom};var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=50};host.Controls.Add(image);host.Controls.Add(bar);string current="idle";double age=0;foreach(string kind in new[]{"idle","blink","wink","pat","wave","left","right"}){string k=kind;var b=new Button{Text=k,AutoSize=true};b.Click+=delegate{current=k;age=0;};bar.Controls.Add(b);}using(var timer=new Timer{Interval=33}){timer.Tick+=delegate{age+=.033;var f=Frame(current);double q=Math.Sin(Math.PI*Math.Min(1,age/1.5));if(current=="blink")f.Blink=q;if(current=="wink")f.Daily=DailyMotion.At(DailyAction.Wink,age);if(current=="pat"||current=="wave")f.ClosedEyes=q;var art=r.Draw(f);var copy=(Bitmap)art.Clone();var prior=image.Image;image.Image=copy;if(prior!=null)prior.Dispose();};host.Shown+=delegate{timer.Start();};Application.Run(host);timer.Stop();}if(image.Image!=null)image.Image.Dispose();}}
}
